// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /health/live)
	GetLiveness(w http.ResponseWriter, r *http.Request)

	// (GET /health/ready)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// DiscoverAccess Discover current Practice and Location authorization.
	// (GET /v1/access)
	DiscoverAccess(w http.ResponseWriter, r *http.Request)
	// InspectSignUpEligibility Validate an invitation or provisioned Platform Operator email.
	// (POST /v1/access/sign-up-eligibility)
	InspectSignUpEligibility(w http.ResponseWriter, r *http.Request)
	// UploadMessageAttachment Store one private Location-scoped pending Message attachment.
	// (POST /v1/attachments)
	UploadMessageAttachment(w http.ResponseWriter, r *http.Request)
	// GetMessageAttachment Read one stored attachment after current Location authorization.
	// (GET /v1/attachments/{attachmentId})
	GetMessageAttachment(w http.ResponseWriter, r *http.Request, attachmentId openapi_types.UUID)
	// RetryInboundMessageAttachment Retry storage of one unavailable inbound attachment in place.
	// (POST /v1/attachments/{attachmentId}/retry-copy)
	RetryInboundMessageAttachment(w http.ResponseWriter, r *http.Request, attachmentId openapi_types.UUID)
	// GetCallingCall Read the winning User's durable active or disposition Call.
	// (GET /v1/calling/calls/{callId})
	GetCallingCall(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID)
	// RecordCallingDisposition Resolve the provider-terminated Call and optionally ensure its one follow-up Task.
	// (POST /v1/calling/calls/{callId}/disposition)
	RecordCallingDisposition(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID)
	// RequestCallingHangup Commit a provider hangup command without claiming termination.
	// (POST /v1/calling/calls/{callId}/hangup)
	RequestCallingHangup(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID)
	// GetCallingCallHistory Read authorized exact-phone Call Engagement History for the active Call.
	// (GET /v1/calling/calls/{callId}/history)
	GetCallingCallHistory(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID, params GetCallingCallHistoryParams)
	// IssueCallingMediaToken Issue a short-lived Telnyx JWT to the current softphone owner.
	// (POST /v1/calling/media-token)
	IssueCallingMediaToken(w http.ResponseWriter, r *http.Request)
	// ListCallingOffers List every current offer the User may accept now.
	// (GET /v1/calling/offers)
	ListCallingOffers(w http.ResponseWriter, r *http.Request)
	// AcceptCallingOffer Atomically claim one current offer and commit its Dial command.
	// (POST /v1/calling/offers/{callId}/accept)
	AcceptCallingOffer(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID)
	// SetCallingReadiness Commit the media-owning session's current technical readiness.
	// (PUT /v1/calling/readiness)
	SetCallingReadiness(w http.ResponseWriter, r *http.Request)
	// AcquireSoftphone Acquire, renew, or explicitly take over the User's softphone lease.
	// (POST /v1/calling/softphone/lease)
	AcquireSoftphone(w http.ResponseWriter, r *http.Request)
	// GetEvents Stream disposable version hints for one authorized scope.
	// (GET /v1/events)
	GetEvents(w http.ResponseWriter, r *http.Request, params GetEventsParams)
	// CreateHandoff Create one authenticated, idempotent Abita handoff.
	// (POST /v1/handoffs)
	CreateHandoff(w http.ResponseWriter, r *http.Request)
	// AcceptInvitation Atomically activate an invitation for the verified identity.
	// (POST /v1/invitations/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request)
	// InspectInvitation Inspect only the scope attached to the presented invitation.
	// (POST /v1/invitations/inspect)
	InspectInvitation(w http.ResponseWriter, r *http.Request)
	// QueryMessageThreads Query phone-led Message Threads in one authorized Location.
	// (POST /v1/message-threads/query)
	QueryMessageThreads(w http.ResponseWriter, r *http.Request)
	// MarkMessageThreadRead Clear the real User's unread marker for one Thread.
	// (POST /v1/message-threads/{threadId}/read)
	MarkMessageThreadRead(w http.ResponseWriter, r *http.Request, threadId openapi_types.UUID)
	// GetMessageThreadTimeline Read one authorized living conversation timeline.
	// (GET /v1/message-threads/{threadId}/timeline)
	GetMessageThreadTimeline(w http.ResponseWriter, r *http.Request, threadId openapi_types.UUID, params GetMessageThreadTimelineParams)
	// SendMessage Durably accept one location-derived outbound Message.
	// (POST /v1/messages)
	SendMessage(w http.ResponseWriter, r *http.Request)
	// CreateMessageFollowUpTask Create at most one OPEN follow-up Task from one Message.
	// (POST /v1/messages/{messageId}/follow-up-task)
	CreateMessageFollowUpTask(w http.ResponseWriter, r *http.Request, messageId openapi_types.UUID)
	// SendMessageAgain Create an explicit new attempt while preserving the original Message.
	// (POST /v1/messages/{messageId}/send-again)
	SendMessageAgain(w http.ResponseWriter, r *http.Request, messageId openapi_types.UUID)
	// GetOperatorCallingTimeline Read one sanitized durable Call timeline as a Platform Operator.
	// (GET /v1/operator/calls/{callId}/timeline)
	GetOperatorCallingTimeline(w http.ResponseWriter, r *http.Request, callId openapi_types.UUID)
	// RequeueOperatorProviderReceipt Requeue one quarantined provider receipt in Platform Operator Support Mode.
	// (POST /v1/operator/practices/{practiceId}/provider-receipts/{receiptReference}/requeue)
	RequeueOperatorProviderReceipt(w http.ResponseWriter, r *http.Request, practiceId openapi_types.UUID, receiptReference string)
	// AddLocation Add a Location as a Platform Operator in Support Mode.
	// (POST /v1/practices/{practiceId}/locations)
	AddLocation(w http.ResponseWriter, r *http.Request, practiceId openapi_types.UUID)
	// GetProviderMessageMedia Serve one short-lived signed outbound attachment to Telnyx.
	// (GET /v1/provider/messaging-media/{attachmentId})
	GetProviderMessageMedia(w http.ResponseWriter, r *http.Request, attachmentId openapi_types.UUID, params GetProviderMessageMediaParams)
	// ReceiveTelnyxMessagingWebhook Verify and durably receipt an inbound Telnyx Message event.
	// (POST /v1/provider/telnyx/messaging-webhooks)
	ReceiveTelnyxMessagingWebhook(w http.ResponseWriter, r *http.Request)
	// ReceiveCorrelatedTelnyxMessagingWebhook Verify and receipt callback-correlated outbound Message evidence.
	// (POST /v1/provider/telnyx/messaging-webhooks/{callbackToken})
	ReceiveCorrelatedTelnyxMessagingWebhook(w http.ResponseWriter, r *http.Request, callbackToken string)
	// ReceiveTelnyxWebhook Verify and durably receipt one raw Telnyx webhook.
	// (POST /v1/provider/telnyx/webhooks)
	ReceiveTelnyxWebhook(w http.ResponseWriter, r *http.Request)
	// EnterSupportMode Enter time-limited Support Mode for one Practice.
	// (POST /v1/support-mode)
	EnterSupportMode(w http.ResponseWriter, r *http.Request)
	// RevokeSupportMode Revoke the real operator's active Support Mode.
	// (DELETE /v1/support-mode/{supportSessionId})
	RevokeSupportMode(w http.ResponseWriter, r *http.Request, supportSessionId openapi_types.UUID)
	// CreateStaffTask Accept one authenticated current Abita create_staff_task command.
	// (POST /v1/tasks)
	CreateStaffTask(w http.ResponseWriter, r *http.Request)
	// QueryTasks Query the authorized Task rail with protected search input.
	// (POST /v1/tasks/query)
	QueryTasks(w http.ResponseWriter, r *http.Request)
	// ReadTask Read one currently authorized Task.
	// (GET /v1/tasks/{taskId})
	ReadTask(w http.ResponseWriter, r *http.Request, taskId openapi_types.UUID)
	// CompleteTask Complete one Task at its last observed version.
	// (POST /v1/tasks/{taskId}/complete)
	CompleteTask(w http.ResponseWriter, r *http.Request, taskId openapi_types.UUID)
	// GetTaskCallHistory Read authorized exact-phone Call Engagement History for one Task.
	// (GET /v1/tasks/{taskId}/history)
	GetTaskCallHistory(w http.ResponseWriter, r *http.Request, taskId openapi_types.UUID, params GetTaskCallHistoryParams)
	// ReopenTask Reopen one completed Task at its last observed version.
	// (POST /v1/tasks/{taskId}/reopen)
	ReopenTask(w http.ResponseWriter, r *http.Request, taskId openapi_types.UUID)
	// RenameTask Rename one open Task at its last observed version.
	// (PUT /v1/tasks/{taskId}/title)
	RenameTask(w http.ResponseWriter, r *http.Request, taskId openapi_types.UUID)
	// GetWorkspace Load the authoritative empty workspace snapshot.
	// (GET /v1/workspace)
	GetWorkspace(w http.ResponseWriter, r *http.Request, params GetWorkspaceParams)
}

